CREATE TABLE IF NOT EXISTS rumo10_conta_planos (conta_id BIGINT UNSIGNED PRIMARY KEY, plano ENUM('gratuito','pago') NOT NULL DEFAULT 'gratuito', atualizado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(conta_id) REFERENCES rumo10_contas(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
